const CORE_JS = "function clamp(value, min, max) {\n  return Math.max(min, Math.min(max, value));\n}\n\nfunction projectBar(bar, nowMs = Date.now()) {\n  if (!bar) return null;\n  const current = Number(bar.current || 0);\n  const maximum = Number(bar.maximum || 0);\n  const increment = Number(bar.increment || 0);\n  const interval = Number(bar.interval || 0);\n  const tickTimeMs = Number(bar.tick_time || 0) * 1000;\n  const fullTimeMs = Number(bar.full_time || 0) * 1000;\n\n  if (maximum <= 0) return {...bar, projected: current, percent: 0, capMs: null};\n  if (current >= maximum) return {...bar, projected: maximum, percent: 100, capMs: nowMs};\n\n  let projected = current;\n  if (interval > 0 && increment > 0 && tickTimeMs > 0 && nowMs >= tickTimeMs) {\n    const ticks = 1 + Math.floor((nowMs - tickTimeMs) / (interval * 1000));\n    projected = clamp(current + ticks * increment, current, maximum);\n  } else if (interval > 0 && increment > 0 && tickTimeMs <= 0 && fullTimeMs > nowMs) {\n    const remainingTicks = Math.ceil((fullTimeMs - nowMs) / (interval * 1000));\n    projected = clamp(maximum - remainingTicks * increment, current, maximum);\n  }\n\n  return {\n    ...bar,\n    projected,\n    percent: clamp((projected / maximum) * 100, 0, 100),\n    capMs: fullTimeMs > 0 ? fullTimeMs : null,\n  };\n}\n\nfunction formatDuration(seconds) {\n  const s = Math.max(0, Math.floor(Number(seconds) || 0));\n  if (s === 0) return 'READY';\n  const h = Math.floor(s / 3600);\n  const m = Math.floor((s % 3600) / 60);\n  const sec = s % 60;\n  if (h > 0) return `${h}h ${m}m`;\n  if (m > 0) return `${m}m ${sec}s`;\n  return `${sec}s`;\n}\n\nfunction timeUntil(ms, nowMs = Date.now()) {\n  if (!ms) return 'UNKNOWN';\n  return formatDuration(Math.max(0, Math.ceil((ms - nowMs) / 1000)));\n}\n\nfunction recommend(snapshot, nowMs = Date.now()) {\n  const energy = projectBar(snapshot.energy, nowMs);\n  const nerve = projectBar(snapshot.nerve, nowMs);\n  const elapsed = Math.max(0, Math.floor((nowMs - Number(snapshot.fetchedAt || nowMs)) / 1000));\n  const drug = Math.max(0, Number(snapshot.cooldowns?.drug || 0) - elapsed);\n\n  if (nerve && nerve.percent >= 90) return {title: 'SPEND NERVE', detail: 'Your nerve is close to capping. Use it before natural regeneration is wasted.'};\n  if (energy && energy.percent >= 90) return {title: 'SPEND ENERGY', detail: 'Your energy is close to capping. Train or use it before natural regeneration is wasted.'};\n  if (drug === 0) return {title: 'DRUG READY', detail: 'Your drug cooldown is clear. Check whether using your planned drug fits your training strategy.'};\n  if (energy && energy.percent >= 60) return {title: 'PLAN TRAINING', detail: 'You have a healthy energy bar. Consider your next gym session before it creeps toward cap.'};\n  return {title: 'REGENERATING', detail: 'Nothing urgent right now. Let your bars regenerate and TornPulse will keep watch.'};\n}\n\nmodule.exports = {clamp, projectBar, formatDuration, timeUntil, recommend};\n";
const TORN_API_JS = "const BASE = 'https://api.torn.com/v2';\nconst TIMEOUT_MS = 12000;\n\nasync function getJson(path, key) {\n  const controller = new AbortController();\n  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);\n  try {\n    const response = await fetch(`${BASE}${path}?comment=TornPulse`, {\n      headers: {Authorization: `ApiKey ${key}`, Accept: 'application/json'},\n      signal: controller.signal,\n    });\n    const json = await response.json().catch(() => null);\n    if (!response.ok || json?.error) {\n      const msg = json?.error?.error || json?.error?.message || `Torn API error (${response.status})`;\n      throw new Error(msg);\n    }\n    return json;\n  } catch (err) {\n    if (err?.name === 'AbortError') throw new Error('Torn API timed out. Check your connection and try again.');\n    throw err;\n  } finally {\n    clearTimeout(timer);\n  }\n}\n\nfunction normalizeBar(raw, nowUnix = Math.floor(Date.now() / 1000)) {\n  if (!raw) throw new Error('Missing Torn bar data.');\n  const current = Number(raw.current);\n  const maximum = Number(raw.maximum);\n  const increment = Number(raw.increment || 0);\n  const interval = Number(raw.interval || 0);\n  const fullSeconds = Math.max(0, Number(raw.full_time || 0));\n  const tickSeconds = Math.max(0, Number(raw.tick_time || 0));\n\n  if (!Number.isFinite(current) || !Number.isFinite(maximum) || maximum <= 0) {\n    throw new Error('Invalid Torn bar data.');\n  }\n\n  return {\n    ...raw,\n    current,\n    maximum,\n    increment,\n    interval,\n    api_full_time_seconds: fullSeconds,\n    api_tick_time_seconds: tickSeconds,\n    full_time: fullSeconds > 0 ? nowUnix + fullSeconds : (current >= maximum ? nowUnix : 0),\n    tick_time: tickSeconds > 0 ? nowUnix + tickSeconds : 0,\n  };\n}\n\nfunction validateBars(payload) {\n  const energyRaw = payload?.bars?.energy;\n  const nerveRaw = payload?.bars?.nerve;\n  if (!energyRaw || !nerveRaw) throw new Error('Unexpected Torn bars response.');\n  return {\n    energy: normalizeBar(energyRaw),\n    nerve: normalizeBar(nerveRaw),\n  };\n}\n\nasync function fetchSnapshot(key) {\n  const [barsPayload, cooldownPayload] = await Promise.all([\n    getJson('/user/bars', key),\n    getJson('/user/cooldowns', key),\n  ]);\n  const {energy, nerve} = validateBars(barsPayload);\n  const cooldowns = cooldownPayload?.cooldowns;\n  if (!cooldowns || !['drug', 'medical', 'booster'].every(k => Number.isFinite(cooldowns[k]))) {\n    throw new Error('Unexpected Torn cooldown response.');\n  }\n  return {energy, nerve, cooldowns, fetchedAt: Date.now(), demo: false};\n}\n\nmodule.exports = {fetchSnapshot, normalizeBar};\n";
const OVERLAY_MODULE_KT = "package com.comfortableai.torncopilot\n\nimport android.content.Intent\nimport android.net.Uri\nimport android.os.Build\nimport android.provider.Settings\nimport androidx.core.content.ContextCompat\nimport com.facebook.react.bridge.Promise\nimport com.facebook.react.bridge.ReactApplicationContext\nimport com.facebook.react.bridge.ReactContextBaseJavaModule\nimport com.facebook.react.bridge.ReactMethod\n\nclass ComfortableOverlayModule(private val appContext: ReactApplicationContext) : ReactContextBaseJavaModule(appContext) {\n  override fun getName(): String = \"ComfortableOverlay\"\n\n  @ReactMethod\n  fun hasPermission(promise: Promise) {\n    promise.resolve(Build.VERSION.SDK_INT < Build.VERSION_CODES.M || Settings.canDrawOverlays(appContext))\n  }\n\n  @ReactMethod\n  fun requestPermission(promise: Promise) {\n    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M || Settings.canDrawOverlays(appContext)) {\n      promise.resolve(true)\n      return\n    }\n    try {\n      val intent = Intent(\n        Settings.ACTION_MANAGE_OVERLAY_PERMISSION,\n        Uri.parse(\"package:${appContext.packageName}\")\n      ).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) }\n      appContext.startActivity(intent)\n      promise.resolve(false)\n    } catch (e: Exception) {\n      promise.reject(\"OVERLAY_SETTINGS\", \"Unable to open Android overlay settings.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun startHud(apiKey: String, promise: Promise) {\n    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M && !Settings.canDrawOverlays(appContext)) {\n      promise.reject(\"OVERLAY_PERMISSION\", \"Display over other apps permission is required.\")\n      return\n    }\n    if (apiKey.isBlank()) {\n      promise.reject(\"API_KEY\", \"A Torn API key is required.\")\n      return\n    }\n    try {\n      val intent = Intent(appContext, ComfortableOverlayService::class.java).apply {\n        action = ComfortableOverlayService.ACTION_START\n        putExtra(ComfortableOverlayService.EXTRA_API_KEY, apiKey)\n      }\n      ContextCompat.startForegroundService(appContext, intent)\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_START\", \"Unable to start TornPulse HUD.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun stopHud(promise: Promise) {\n    try {\n      val intent = Intent(appContext, ComfortableOverlayService::class.java).apply {\n        action = ComfortableOverlayService.ACTION_STOP\n      }\n      appContext.startService(intent)\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_STOP\", \"Unable to stop TornPulse HUD.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun isRunning(promise: Promise) {\n    promise.resolve(ComfortableOverlayService.isRunning)\n  }\n}\n";
const OVERLAY_PACKAGE_KT = "package com.comfortableai.torncopilot\n\nimport com.facebook.react.ReactPackage\nimport com.facebook.react.bridge.NativeModule\nimport com.facebook.react.bridge.ReactApplicationContext\nimport com.facebook.react.uimanager.ViewManager\n\nclass ComfortableOverlayPackage : ReactPackage {\n  override fun createNativeModules(reactContext: ReactApplicationContext): List<NativeModule> =\n    listOf(ComfortableOverlayModule(reactContext))\n\n  override fun createViewManagers(reactContext: ReactApplicationContext): List<ViewManager<*, *>> =\n    emptyList()\n}\n";
const OVERLAY_SERVICE_KT = "package com.comfortableai.torncopilot\n\nimport android.app.NotificationChannel\nimport android.app.NotificationManager\nimport android.app.PendingIntent\nimport android.app.Service\nimport android.content.Context\nimport android.content.Intent\nimport android.content.pm.ServiceInfo\nimport android.graphics.Color\nimport android.graphics.PixelFormat\nimport android.graphics.Typeface\nimport android.graphics.drawable.GradientDrawable\nimport android.os.Build\nimport android.os.Handler\nimport android.os.IBinder\nimport android.os.Looper\nimport android.os.SystemClock\nimport android.text.Spannable\nimport android.text.SpannableString\nimport android.text.style.ForegroundColorSpan\nimport android.view.Gravity\nimport android.view.MotionEvent\nimport android.view.View\nimport android.view.WindowManager\nimport android.widget.LinearLayout\nimport android.widget.TextView\nimport androidx.core.app.NotificationCompat\nimport androidx.core.app.ServiceCompat\nimport org.json.JSONObject\nimport java.net.HttpURLConnection\nimport java.net.URL\nimport java.util.concurrent.Executors\nimport java.util.concurrent.ScheduledFuture\nimport java.util.concurrent.TimeUnit\nimport kotlin.math.abs\nimport kotlin.math.max\nimport kotlin.math.min\n\nclass ComfortableOverlayService : Service() {\n  companion object {\n    const val ACTION_START = \"com.comfortableai.torncopilot.START_HUD\"\n    const val ACTION_STOP = \"com.comfortableai.torncopilot.STOP_HUD\"\n    const val EXTRA_API_KEY = \"comfortable_api_key\"\n    private const val CHANNEL_ID = \"comfortable-hud\"\n    private const val NOTIFICATION_ID = 606\n    @Volatile var isRunning: Boolean = false\n  }\n\n  private data class BarState(\n    val current: Int,\n    val maximum: Int,\n    val increment: Int,\n    val interval: Int,\n    val tickTime: Int,\n    val fullTime: Int,\n  )\n\n  private data class Snapshot(\n    val energy: BarState,\n    val nerve: BarState,\n    val drug: Int,\n    val booster: Int,\n    val medical: Int,\n    val receivedElapsed: Long,\n  )\n\n  private val handler = Handler(Looper.getMainLooper())\n  private val executor = Executors.newSingleThreadScheduledExecutor()\n  private var pollFuture: ScheduledFuture<*>? = null\n  private var apiKey: String? = null\n  @Volatile private var snapshot: Snapshot? = null\n  @Volatile private var lastError: String? = null\n\n  private lateinit var windowManager: WindowManager\n  private var overlayView: LinearLayout? = null\n  private var headerText: TextView? = null\n  private var barsText: TextView? = null\n  private var cooldownText: TextView? = null\n  private var detailText: TextView? = null\n  private var params: WindowManager.LayoutParams? = null\n  private var expanded = false\n\n  private val ticker = object : Runnable {\n    override fun run() {\n      render()\n      handler.postDelayed(this, 1000)\n    }\n  }\n\n  override fun onCreate() {\n    super.onCreate()\n    windowManager = getSystemService(Context.WINDOW_SERVICE) as WindowManager\n    handler.post(ticker)\n  }\n\n  override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {\n    if (intent?.action == ACTION_STOP) {\n      stopSelf()\n      return START_NOT_STICKY\n    }\n\n    startAsForeground()\n    val incomingKey = intent?.getStringExtra(EXTRA_API_KEY)\n    if (!incomingKey.isNullOrBlank()) apiKey = incomingKey\n\n    if (apiKey.isNullOrBlank()) {\n      stopSelf()\n      return START_NOT_STICKY\n    }\n\n    try {\n      ensureOverlay()\n    } catch (_: Exception) {\n      stopSelf()\n      return START_NOT_STICKY\n    }\n\n    isRunning = true\n    startPolling()\n    return START_NOT_STICKY\n  }\n\n  override fun onBind(intent: Intent?): IBinder? = null\n\n  override fun onDestroy() {\n    isRunning = false\n    apiKey = null\n    handler.removeCallbacks(ticker)\n    pollFuture?.cancel(true)\n    executor.shutdownNow()\n    overlayView?.let {\n      try { windowManager.removeView(it) } catch (_: Exception) {}\n    }\n    overlayView = null\n    stopForeground(STOP_FOREGROUND_REMOVE)\n    super.onDestroy()\n  }\n\n  private fun startAsForeground() {\n    val manager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager\n    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {\n      manager.createNotificationChannel(\n        NotificationChannel(CHANNEL_ID, \"TornPulse HUD\", NotificationManager.IMPORTANCE_LOW).apply {\n          description = \"Keeps the TornPulse floating Torn HUD running\"\n          setShowBadge(false)\n        }\n      )\n    }\n\n    val launchIntent = packageManager.getLaunchIntentForPackage(packageName)\n    val launchPending = launchIntent?.let {\n      PendingIntent.getActivity(this, 0, it, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n    }\n    val stopIntent = Intent(this, ComfortableOverlayService::class.java).apply { action = ACTION_STOP }\n    val stopPending = PendingIntent.getService(this, 1, stopIntent, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n\n    val notification = NotificationCompat.Builder(this, CHANNEL_ID)\n      .setSmallIcon(applicationInfo.icon)\n      .setContentTitle(\"TornPulse HUD is running\")\n      .setContentText(\"Energy and Nerve are staying visible over your apps.\")\n      .setOngoing(true)\n      .setOnlyAlertOnce(true)\n      .setCategory(NotificationCompat.CATEGORY_SERVICE)\n      .setPriority(NotificationCompat.PRIORITY_LOW)\n      .setContentIntent(launchPending)\n      .addAction(android.R.drawable.ic_menu_close_clear_cancel, \"Stop HUD\", stopPending)\n      .build()\n\n    if (Build.VERSION.SDK_INT >= 34) {\n      ServiceCompat.startForeground(this, NOTIFICATION_ID, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE)\n    } else {\n      startForeground(NOTIFICATION_ID, notification)\n    }\n  }\n\n  private fun ensureOverlay() {\n    if (overlayView != null) return\n\n    val root = LinearLayout(this).apply {\n      orientation = LinearLayout.VERTICAL\n      setPadding(dp(10), dp(6), dp(10), dp(6))\n      minimumWidth = dp(220)\n      elevation = dp(12).toFloat()\n      background = GradientDrawable().apply {\n        shape = GradientDrawable.RECTANGLE\n        cornerRadius = dp(12).toFloat()\n        setColor(Color.argb(232, 8, 10, 14))\n        setStroke(dp(1), Color.argb(190, 196, 61, 61))\n      }\n    }\n\n    val accentRail = View(this).apply { setBackgroundColor(Color.rgb(196, 61, 61)) }\n    root.addView(accentRail, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, dp(2)).apply { bottomMargin = dp(5) })\n\n    headerText = makeText(\"TORNPULSE \u2022 CONNECTING\", 8f, Color.rgb(156, 164, 176), true).also {\n      it.letterSpacing = 0.12f\n      it.textAlignment = View.TEXT_ALIGNMENT_CENTER\n      root.addView(it, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n    }\n    barsText = makeText(\"ϟ -- / --   ✺ -- / --\", 15f, Color.rgb(241, 243, 245), true).also {\n      it.setPadding(0, dp(2), 0, 0)\n      it.maxLines = 1\n      it.textAlignment = View.TEXT_ALIGNMENT_CENTER\n      root.addView(it, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n    }\n    cooldownText = makeText(\"💊 --   •   🥤 --   •   ✚ --\", 9f, Color.rgb(165, 173, 184), true).also {\n      it.setPadding(0, dp(3), 0, 0)\n      it.maxLines = 1\n      it.textAlignment = View.TEXT_ALIGNMENT_CENTER\n      root.addView(it, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n    }\n    detailText = makeText(\"Connecting to Torn\u2026\", 10f, Color.rgb(145, 156, 175), false).also {\n      it.setPadding(0, dp(5), 0, 0)\n      it.setLineSpacing(dp(1).toFloat(), 1f)\n      it.visibility = View.GONE\n      root.addView(it)\n    }\n\n    val prefs = getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n    val display = resources.displayMetrics\n    val savedX = prefs.getInt(\"x\", dp(12))\n    val savedY = prefs.getInt(\"y\", dp(120))\n    val type = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY else WindowManager.LayoutParams.TYPE_PHONE\n\n    val lp = WindowManager.LayoutParams(\n      WindowManager.LayoutParams.WRAP_CONTENT,\n      WindowManager.LayoutParams.WRAP_CONTENT,\n      type,\n      WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,\n      PixelFormat.TRANSLUCENT\n    ).apply {\n      gravity = Gravity.TOP or Gravity.START\n      x = min(max(0, savedX), max(0, display.widthPixels - dp(206)))\n      y = max(dp(36), savedY)\n    }\n\n    var initialX = 0\n    var initialY = 0\n    var initialTouchX = 0f\n    var initialTouchY = 0f\n    var moved = false\n\n    root.setOnTouchListener { _, event ->\n      when (event.actionMasked) {\n        MotionEvent.ACTION_DOWN -> {\n          initialX = lp.x\n          initialY = lp.y\n          initialTouchX = event.rawX\n          initialTouchY = event.rawY\n          moved = false\n          true\n        }\n        MotionEvent.ACTION_MOVE -> {\n          val dx = event.rawX - initialTouchX\n          val dy = event.rawY - initialTouchY\n          if (abs(dx) > dp(4) || abs(dy) > dp(4)) moved = true\n          if (moved) {\n            val width = max(root.width, dp(236))\n            val height = max(root.height, dp(60))\n            lp.x = min(max(0, initialX + dx.toInt()), max(0, display.widthPixels - width))\n            lp.y = min(max(dp(30), initialY + dy.toInt()), max(dp(30), display.heightPixels - height - dp(30)))\n            try { windowManager.updateViewLayout(root, lp) } catch (_: Exception) {}\n          }\n          true\n        }\n        MotionEvent.ACTION_UP -> {\n          if (!moved) {\n            expanded = !expanded\n            detailText?.visibility = if (expanded) View.VISIBLE else View.GONE\n            render()\n          }\n          prefs.edit().putInt(\"x\", lp.x).putInt(\"y\", lp.y).apply()\n          true\n        }\n        else -> false\n      }\n    }\n\n    windowManager.addView(root, lp)\n    overlayView = root\n    params = lp\n    render()\n  }\n\n  private fun makeText(value: String, size: Float, color: Int, bold: Boolean): TextView =\n    TextView(this).apply {\n      text = value\n      textSize = size\n      setTextColor(color)\n      typeface = if (bold) Typeface.DEFAULT_BOLD else Typeface.DEFAULT\n      includeFontPadding = false\n    }\n\n  private fun renderBars(energyText: String, nerveText: String) {\n    val left = \"ϟ $energyText\"\n    val gap = \"   \"\n    val right = \"✺ $nerveText\"\n    val text = left + gap + right\n    val styled = SpannableString(text)\n    styled.setSpan(ForegroundColorSpan(Color.rgb(83, 185, 29)), 0, left.length, Spannable.SPAN_EXCLUSIVE_EXCLUSIVE)\n    val nerveStart = left.length + gap.length\n    styled.setSpan(ForegroundColorSpan(Color.rgb(226, 74, 41)), nerveStart, text.length, Spannable.SPAN_EXCLUSIVE_EXCLUSIVE)\n    barsText?.text = styled\n  }\n\n  private fun startPolling() {\n    if (pollFuture == null || pollFuture?.isCancelled == true) {\n      pollFuture = executor.scheduleWithFixedDelay({ fetchSnapshot() }, 0, 60, TimeUnit.SECONDS)\n    } else {\n      executor.execute { fetchSnapshot() }\n    }\n  }\n\n  private fun fetchSnapshot() {\n    val key = apiKey ?: return\n    try {\n      val bars = getJson(\"/user/bars\", key).getJSONObject(\"bars\")\n      val cooldowns = getJson(\"/user/cooldowns\", key).getJSONObject(\"cooldowns\")\n      val next = Snapshot(\n        energy = readBar(bars.getJSONObject(\"energy\")),\n        nerve = readBar(bars.getJSONObject(\"nerve\")),\n        drug = cooldowns.optInt(\"drug\", 0),\n        booster = cooldowns.optInt(\"booster\", 0),\n        medical = cooldowns.optInt(\"medical\", 0),\n        receivedElapsed = SystemClock.elapsedRealtime(),\n      )\n      snapshot = next\n      lastError = null\n      handler.post { render() }\n    } catch (e: Exception) {\n      lastError = e.message ?: \"Connection issue\"\n      handler.post { render() }\n    }\n  }\n\n  private fun getJson(path: String, key: String): JSONObject {\n    val connection = URL(\"https://api.torn.com/v2$path?comment=TornPulse-HUD\").openConnection() as HttpURLConnection\n    connection.connectTimeout = 12000\n    connection.readTimeout = 12000\n    connection.requestMethod = \"GET\"\n    connection.setRequestProperty(\"Authorization\", \"ApiKey $key\")\n    connection.setRequestProperty(\"Accept\", \"application/json\")\n    connection.setRequestProperty(\"User-Agent\", \"TornPulse/0.7.2\")\n    return try {\n      val code = connection.responseCode\n      val stream = if (code in 200..299) connection.inputStream else connection.errorStream\n      val body = stream?.bufferedReader()?.use { it.readText() } ?: \"{}\"\n      val json = JSONObject(body)\n      if (code !in 200..299 || json.has(\"error\")) {\n        val error = json.optJSONObject(\"error\")\n        throw IllegalStateException(error?.optString(\"error\") ?: error?.optString(\"message\") ?: \"Torn API error ($code)\")\n      }\n      json\n    } finally {\n      connection.disconnect()\n    }\n  }\n\n  private fun readBar(json: JSONObject): BarState {\n    val bar = BarState(\n      current = json.optInt(\"current\", 0),\n      maximum = json.optInt(\"maximum\", 0),\n      increment = json.optInt(\"increment\", 0),\n      interval = json.optInt(\"interval\", 0),\n      tickTime = max(0, json.optInt(\"tick_time\", 0)),\n      fullTime = max(0, json.optInt(\"full_time\", 0)),\n    )\n    if (bar.maximum <= 0) throw IllegalStateException(\"Invalid Torn bar response\")\n    return bar\n  }\n\n  private fun projected(bar: BarState, elapsed: Int): Int {\n    if (bar.current >= bar.maximum) return bar.maximum\n    if (bar.interval <= 0 || bar.increment <= 0) return bar.current\n    val firstTick = if (bar.tickTime > 0) bar.tickTime else bar.interval\n    if (elapsed < firstTick) return bar.current\n    val ticks = 1 + (elapsed - firstTick) / bar.interval\n    return min(bar.maximum, bar.current + ticks * bar.increment)\n  }\n\n  private fun remaining(initial: Int, elapsed: Int): Int = max(0, initial - elapsed)\n\n  private fun render() {\n    val snap = snapshot\n    if (snap == null) {\n      headerText?.text = if (lastError == null) \"TORNPULSE • CONNECTING\" else \"TORNPULSE • OFFLINE\"\n      renderBars(\"-- / --\", \"-- / --\")\n      cooldownText?.text = \"💊 --   •   🥤 --   •   ✚ --\"\n      detailText?.text = lastError ?: \"Connecting to Torn\u2026\"\n      return\n    }\n\n    val elapsed = max(0, ((SystemClock.elapsedRealtime() - snap.receivedElapsed) / 1000L).toInt())\n    val energy = projected(snap.energy, elapsed)\n    val nerve = projected(snap.nerve, elapsed)\n    val stale = elapsed > 120 || lastError != null\n\n    headerText?.text = if (stale) \"TORNPULSE • CHECKING\" else \"TORNPULSE • LIVE\"\n    headerText?.setTextColor(if (stale) Color.rgb(213, 165, 46) else Color.rgb(196, 61, 61))\n    renderBars(\"$energy / ${snap.energy.maximum}\", \"$nerve / ${snap.nerve.maximum}\")\n\n    val energyFull = if (energy >= snap.energy.maximum) \"CAPPED\" else formatDuration(remaining(snap.energy.fullTime, elapsed))\n    val nerveFull = if (nerve >= snap.nerve.maximum) \"CAPPED\" else formatDuration(remaining(snap.nerve.fullTime, elapsed))\n    val drug = formatDuration(remaining(snap.drug, elapsed))\n    val booster = formatDuration(remaining(snap.booster, elapsed))\n    val medical = formatDuration(remaining(snap.medical, elapsed))\n    val errorLine = lastError?.let { \"\\nLast refresh failed \u2022 retrying automatically\" } ?: \"\"\n\n    cooldownText?.text = \"💊 $drug   •   🥤 $booster   •   ✚ $medical\"\n    detailText?.text = \"FULL   ϟ $energyFull   •   ✺ $nerveFull\\nCOOLDOWNS   💊 $drug   •   🥤 $booster   •   ✚ $medical$errorLine\\nTap to collapse   •   Drag to move\"\n  }\n\n  private fun formatDuration(totalSeconds: Int): String {\n    if (totalSeconds <= 0) return \"READY\"\n    val hours = totalSeconds / 3600\n    val minutes = (totalSeconds % 3600) / 60\n    val seconds = totalSeconds % 60\n    return when {\n      hours > 0 -> \"${hours}h ${minutes}m\"\n      minutes > 0 -> \"${minutes}m ${seconds}s\"\n      else -> \"${seconds}s\"\n    }\n  }\n\n  private fun dp(value: Int): Int = (value * resources.displayMetrics.density).toInt()\n}\n";

function ensurePermission(manifest, name) {
  manifest['uses-permission'] = manifest['uses-permission'] || [];
  const exists = manifest['uses-permission'].some(item => item?.$?.['android:name'] === name);
  if (!exists) manifest['uses-permission'].push({$: {'android:name': name}});
}

function withComfortableHud(config) {
  config = withAndroidManifest(config, config => {
    const manifest = config.modResults.manifest;
    ensurePermission(manifest, 'android.permission.SYSTEM_ALERT_WINDOW');
    ensurePermission(manifest, 'android.permission.FOREGROUND_SERVICE');
    ensurePermission(manifest, 'android.permission.FOREGROUND_SERVICE_SPECIAL_USE');
    ensurePermission(manifest, 'android.permission.POST_NOTIFICATIONS');

    const application = manifest.application?.[0];
    if (!application) throw new Error('TornPulse: Android application manifest node not found.');
    application.service = application.service || [];
    const serviceName = `${PACKAGE_NAME}.ComfortableOverlayService`;
    const exists = application.service.some(service => {
      const name = service?.$?.['android:name'];
      return name === serviceName || name === '.ComfortableOverlayService';
    });
    if (!exists) {
      application.service.push({
        $: {
          'android:name': serviceName,
          'android:exported': 'false',
          'android:stopWithTask': 'false',
          'android:foregroundServiceType': 'specialUse',
        },
        property: [{
          $: {
            'android:name': 'android.app.PROPERTY_SPECIAL_USE_FGS_SUBTYPE',
            'android:value': 'Floating Torn status HUD for the user while other apps are open',
          },
        }],
      });
    }
    return config;
  });

  config = withMainApplication(config, config => {
    let source = config.modResults.contents;
    if (!source.includes('ComfortableOverlayPackage()')) {
      if (config.modResults.language === 'kt' || source.includes('PackageList(this).packages.apply {')) {
        const marker = 'PackageList(this).packages.apply {';
        if (!source.includes(marker)) throw new Error('TornPulse: could not find Kotlin package list in MainApplication.');
        source = source.replace(marker, `${marker}\n              add(ComfortableOverlayPackage())`);
      } else {
        const marker = 'List<ReactPackage> packages = new PackageList(this).getPackages();';
        if (!source.includes(marker)) throw new Error('TornPulse: could not find Java package list in MainApplication.');
        source = source.replace(marker, `${marker}\n        packages.add(new ComfortableOverlayPackage());`);
      }
    }
    config.modResults.contents = source;
    return config;
  });

  config = withDangerousMod(config, ['android', async config => {
    const root = config.modRequest.projectRoot;
    const srcDir = path.join(root, 'src');
    fs.mkdirSync(srcDir, {recursive: true});

    // Patch the JS app used by the release bundle after the workflow restores /src.
    fs.writeFileSync(path.join(root, 'App.js'), APP_JS, 'utf8');
    fs.writeFileSync(path.join(root, 'core.js'), CORE_JS, 'utf8');
    fs.writeFileSync(path.join(root, 'tornApi.js'), TORN_API_JS, 'utf8');
    fs.writeFileSync(path.join(srcDir, 'core.js'), CORE_JS, 'utf8');
    fs.writeFileSync(path.join(srcDir, 'tornApi.js'), TORN_API_JS, 'utf8');

    const javaDir = path.join(root, 'android', 'app', 'src', 'main', 'java', ...PACKAGE_NAME.split('.'));
    fs.mkdirSync(javaDir, {recursive: true});
    fs.writeFileSync(path.join(javaDir, 'ComfortableOverlayModule.kt'), OVERLAY_MODULE_KT, 'utf8');
    fs.writeFileSync(path.join(javaDir, 'ComfortableOverlayPackage.kt'), OVERLAY_PACKAGE_KT, 'utf8');
    fs.writeFileSync(path.join(javaDir, 'ComfortableOverlayService.kt'), OVERLAY_SERVICE_KT, 'utf8');
    return config;
  }]);

  return config;
}

module.exports = ({ config }) => {
  config = {...config};
  config.name = 'TornPulse';
  config.slug = 'comfortable-ai';
  config.version = '0.7.2';
  config.orientation = 'portrait';
  config.userInterfaceStyle = 'dark';
  config.android = {
    ...(config.android || {}),
    package: PACKAGE_NAME,
    versionCode: 17,
  };

  const plugins = Array.isArray(config.plugins) ? [...config.plugins] : [];
  const pluginName = entry => Array.isArray(entry) ? entry[0] : entry;
  if (!plugins.some(entry => pluginName(entry) === 'expo-notifications')) {
    plugins.push(['expo-notifications', {defaultChannel: 'torn-alerts'}]);
  }
  if (!plugins.some(entry => pluginName(entry) === 'expo-secure-store')) {
    plugins.push('expo-secure-store');
  }
  config.plugins = plugins;

  return withComfortableHud(config);
};
